package br.com.gestao.dashboard; import br.com.gestao.product.*; import br.com.gestao.finance.*; import br.com.gestao.sale.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final ProductRepository products;private final FinancialEntryRepository finance;private final SaleRepository sales;public DashboardController(ProductRepository p,FinancialEntryRepository f,SaleRepository s){products=p;finance=f;sales=s;} @GetMapping public Map<String,Object> summary(){var ps=products.findAll();var fs=finance.findAll();BigDecimal income=fs.stream().filter(x->x.getType()==EntryType.INCOME&&x.isPaid()).map(FinancialEntry::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal expense=fs.stream().filter(x->x.getType()==EntryType.EXPENSE&&x.isPaid()).map(FinancialEntry::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);long low=ps.stream().filter(p->p.getStock()<=p.getMinStock()).count();return Map.of("products",ps.size(),"stockUnits",ps.stream().mapToInt(Product::getStock).sum(),"lowStock",low,"sales",sales.count(),"income",income,"expense",expense,"balance",income.subtract(expense));}}
